suppressPackageStartupMessages(library(data.table))
root<-".";out<-file.path(root,"results_tables");logd<-file.path(root,"logs")
required<-c("depmap_crc_lipid_dependency_summary.tsv","project_score_sanger_audit_summary.tsv","tcga_cptac_validation_manifest.tsv","tcga_expression_cna_correlations.tsv","tcga_os_cox_results.tsv","tcga_coad_adjusted_cox_results.tsv","GSE39582_validation_qc.tsv","GSE39582_stage_association_results.tsv","GSE39582_adjusted_os_cox_results.tsv","GSE18105_validation_qc.tsv","GSE18105_metastasis_association_results.tsv")
missing<-required[!file.exists(file.path(out,required))];if(length(missing))stop("Missing integration inputs: ",paste(missing,collapse=", "))
d3<-fread(file.path(out,"depmap_crc_lipid_dependency_summary.tsv"));ps<-fread(file.path(out,"project_score_sanger_audit_summary.tsv"));g395<-fread(file.path(out,"GSE39582_validation_qc.tsv"));g181<-fread(file.path(out,"GSE18105_validation_qc.tsv"))
if(d3$fdr_lt_0_05!=77)stop("DepMap selective-gene count changed");if(ps$sanger_crc_models!=29)stop("Project Score CRC count changed");if(g395$tumor_samples!=566)stop("GSE39582 tumor count changed");if(g181$cancer_lcm_samples!=77)stop("GSE18105 LCM count changed")
evidence<-data.table(domain=c("DepMap CRC dependency discovery","Project Score Sanger replication","DepMap expression/CNA robustness","TCGA patient multi-omics","CPTAC protein layer","TCGA clinical outcome","GSE39582 independent patient cohort","GSE18105 independent metastasis cohort"),primary_result=c("77 core genes CRC-selective at BH<0.05; FASN/SCD among anchors","FASN and SCD concordant at BH<0.05; 28/29 CRC models overlap DepMap","No anchor expression-dependency association survived BH in 49 complete cases","COAD expression-CNA correlations; SCD/FASN-SCD T-stage exploratory findings","FASN and ACACA detected; SCD/SREBF1 not returned","Adjusted COAD SCD and scores null; no robust OS biomarker","FASN stage association and unadjusted OS association; adjusted FASN borderline; SCD null","No FASN/SCD metastasis association; no sample-level stage/OS fields"),status=c("supported","supported with non-independence caveat","negative robustness result","supportive/exploratory","partial support","not supported as independent prognostic claim","supportive but borderline after adjustment","negative secondary replication"),analysis_n=c(61,29,49,454,97,442,562,77),event_n=c(NA,NA,NA,NA,NA,96,191,NA))
fwrite(evidence,file.path(out,"final_integrated_evidence_table.tsv"),sep="\t",na="NA")
checks<-data.table(check=c("required_inputs_present","DepMap_selective_count_77","ProjectScore_crc_count_29","GSE39582_tumor_count_566","GSE18105_cancer_LCM_count_77"),passed=c(length(missing)==0,d3$fdr_lt_0_05==77,ps$sanger_crc_models==29,g395$tumor_samples==566,g181$cancer_lcm_samples==77));fwrite(checks,file.path(out,"final_integration_self_checks.tsv"),sep="\t",na="NA");if(!all(checks$passed))stop("Final integration self-check failed")
capture.output(sessionInfo(),file=file.path(logd,"final_integration_sessionInfo.txt"));cat("Final integration audit completed\n")
